//! The module list, generated by `cargo xtask module new|remove`; edit it through that command.

use hrn_kernel::{Registry, Result};

// With every module feature off the body never fails, yet the signature is the seam
// registration lines are generated into.
#[cfg_attr(
    not(any(
        feature = "agy",
        feature = "ast",
        feature = "browser",
        feature = "checkpoint",
        feature = "debug",
        feature = "desktop",
        feature = "edit",
        feature = "eval",
        feature = "find",
        feature = "fs",
        feature = "github",
        feature = "hooks",
        feature = "lsp",
        feature = "memory",
        feature = "meta",
        feature = "shell",
        feature = "web"
    )),
    expect(
        clippy::unnecessary_wraps,
        reason = "stable signature for generated registration"
    )
)]
pub(crate) fn registry(registry: Registry) -> Result<Registry> {
    #[cfg(feature = "agy")]
    let registry = registry.module("agy", hrn_mod_agy::register)?;
    #[cfg(feature = "ast")]
    let registry = registry.module("ast", hrn_mod_ast::register)?;
    #[cfg(feature = "browser")]
    let registry = registry.module("browser", hrn_mod_browser::register)?;
    #[cfg(feature = "checkpoint")]
    let registry = registry.module("checkpoint", hrn_mod_checkpoint::register)?;
    #[cfg(feature = "debug")]
    let registry = registry.module("debug", hrn_mod_debug::register)?;
    #[cfg(feature = "desktop")]
    let registry = registry.module("desktop", hrn_mod_desktop::register)?;
    #[cfg(feature = "edit")]
    let registry = registry.module("edit", hrn_mod_edit::register)?;
    #[cfg(feature = "eval")]
    let registry = registry.module("eval", hrn_mod_eval::register)?;
    #[cfg(feature = "find")]
    let registry = registry.module("find", hrn_mod_find::register)?;
    #[cfg(feature = "fs")]
    let registry = registry.module("fs", hrn_mod_fs::register)?;
    #[cfg(feature = "github")]
    let registry = registry.module("github", hrn_mod_github::register)?;
    #[cfg(feature = "hooks")]
    let registry = registry.module("hooks", hrn_mod_hooks::register)?;
    #[cfg(feature = "lsp")]
    let registry = registry.module("lsp", hrn_mod_lsp::register)?;
    #[cfg(feature = "memory")]
    let registry = registry.module("memory", hrn_mod_memory::register)?;
    #[cfg(feature = "meta")]
    let registry = registry.module("meta", hrn_mod_meta::register)?;
    #[cfg(feature = "shell")]
    let registry = registry.module("shell", hrn_mod_shell::register)?;
    #[cfg(feature = "web")]
    let registry = registry.module("web", hrn_mod_web::register)?;
    Ok(registry)
}

/// Dispatch `/memory [view|stats|search|enqueue|clear]` to `hrn-mod-memory` when compiled in.
#[cfg(feature = "memory")]
pub(crate) fn run_memory_command(
    db_path: &std::path::Path,
    cwd: &std::path::Path,
    session_id: Option<&str>,
    arg: Option<&str>,
    fallback: Option<&str>,
) -> Result<String> {
    hrn_mod_memory::admin::run_command(db_path, cwd, session_id, arg, fallback)
}

/// Fallback when the optional `memory` module is compiled out (`--no-default-features`).
#[cfg(not(feature = "memory"))]
pub(crate) fn run_memory_command(
    _db_path: &std::path::Path,
    _cwd: &std::path::Path,
    _session_id: Option<&str>,
    _arg: Option<&str>,
    _fallback: Option<&str>,
) -> Result<String> {
    Err(hrn_kernel::HrnError::Config(
        "the `memory` module is disabled in this build".to_owned(),
    ))
}

/// Dispatch `/agy [status|[flags] <prompt>]` to `hrn-mod-agy` when compiled in.
#[cfg(feature = "agy")]
pub(crate) fn run_agy_command(
    handle: &tokio::runtime::Handle,
    tx: hrn_tui::UiSender,
    cwd: std::path::PathBuf,
    arg: Option<&str>,
) -> Result<String> {
    let parsed =
        hrn_mod_agy::parse_slash_command(arg, cwd).map_err(hrn_kernel::HrnError::Config)?;
    let Some(req) = parsed else {
        return Ok(hrn_mod_agy::status_report());
    };
    let cfg = hrn_mod_agy::AgyConfig::from_env();
    if hrn_mod_agy::discover_agy_binary(cfg.binary.as_deref()).is_none() {
        return Err(hrn_kernel::HrnError::Config(
            "official `agy` binary not found on PATH (install `agy` or set HRN_AGY_BIN)".to_owned(),
        ));
    }
    let isolated = req.needs_worktree();
    handle.spawn(async move {
        let cancel = hrn_kernel::CancelFlag::new();
        let report = match hrn_mod_agy::run_agy(&cfg, &req, &cancel, |_| {}).await {
            Ok(resp) => hrn_mod_agy::format_slash_response(&resp),
            Err(err) => format!("[agy error] {err}"),
        };
        let _ = tx.send(hrn_tui::UiEvent::Report(report));
    });
    if isolated {
        Ok("running agy in an isolated git worktree (result will arrive when done)…".to_owned())
    } else {
        Ok("running agy (result will arrive when done)…".to_owned())
    }
}

/// Fallback when the optional `agy` module is compiled out (`--no-default-features`).
#[cfg(not(feature = "agy"))]
pub(crate) fn run_agy_command(
    _handle: &tokio::runtime::Handle,
    _tx: hrn_tui::UiSender,
    _cwd: std::path::PathBuf,
    _arg: Option<&str>,
) -> Result<String> {
    Err(hrn_kernel::HrnError::Config(
        "the `agy` module is disabled in this build".to_owned(),
    ))
}

/// Return whether optional module `id` was compiled into this binary.
pub(crate) fn is_compiled(id: &str) -> bool {
    let compiled: &[&str] = &[
        #[cfg(feature = "shell")]
        "shell",
        #[cfg(feature = "browser")]
        "browser",
        #[cfg(feature = "edit")]
        "edit",
    ];
    compiled.contains(&id)
}
